//! National Dex species list, compiled in from `data/species.tsv`
//! (generated by `tools/export_species.py` from PokéAPI data).

use std::sync::OnceLock;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Species {
    pub id: u16,
    pub name: &'static str,
    /// Generation the species was introduced in.
    pub generation: u8,
    /// One or two lowercase type names, e.g. `["grass", "poison"]`.
    pub types: Vec<&'static str>,
}

const TSV: &str = include_str!("../data/species.tsv");

/// All species, indexed so that `all()[n - 1]` is National Dex #n.
pub fn all() -> &'static [Species] {
    static LIST: OnceLock<Vec<Species>> = OnceLock::new();
    LIST.get_or_init(|| {
        TSV.lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
            .map(|l| {
                let mut f = l.split('\t');
                let mut next = || f.next().expect("species.tsv has 4 columns");
                Species {
                    id: next().parse().expect("species id"),
                    name: next(),
                    generation: next().parse().expect("species generation"),
                    types: next().split(',').collect(),
                }
            })
            .collect()
    })
}

pub fn get(id: u16) -> Option<&'static Species> {
    all().get(usize::from(id).checked_sub(1)?)
}

/// Species name, or `#id` if the list doesn't cover it.
pub fn name(id: u16) -> String {
    get(id).map_or_else(|| format!("#{id}"), |s| s.name.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_dense_and_ordered() {
        assert!(all().len() >= 151);
        assert!(all().iter().enumerate().all(|(i, s)| usize::from(s.id) == i + 1));
    }

    #[test]
    fn lookups() {
        let pikachu = get(25).unwrap();
        assert_eq!((pikachu.name, pikachu.generation), ("Pikachu", 1));
        assert_eq!(get(1).unwrap().types, ["grass", "poison"]);
        assert_eq!(get(0), None);
        assert_eq!(name(9999), "#9999");
    }
}
